  ok('the payout says it is incomplete and why', /Incomplete: what is not known is not counted/.test(await text(page.getByTestId('chef-payout-incomplete'))) && /Recompletion dishes have no prize/.test(await text(page.getByTestId('chef-payout-incomplete'))))
