  const switches = await page.getByTestId('chef-proposal-may-change').locator('input[type="checkbox"]').evaluateAll((list) => list.map((el) => el.checked))
  ok(`what may change is five switches - recipes, weights and threshold amounts on to start with (${switches.join(' ')})`, switches.join() === 'true,true,true,false,false' && /Base recipe quantities.*Basket weights.*Threshold amounts.*Threshold opening days.*Blocker quantities by segment/.test(await text(page.getByTestId('chef-proposal-may-change'))))
  ok('what is never changed is said beside them', /Never changed: which ingredients a dish needs, the segments and what they open, basket sizes and the most a basket gives, pantry caps, prizes, special sources and jokers, the dates, the targets, catch-up presets, pricing odds\. Nothing is added/.test(await text(page.getByTestId('chef-proposal-may-change'))))
  ok('the targets are said in words: who is counted, on which day, and that every segment is judged', /On day 14, 80% of the players of each segment sitting in FU\. Counted: players in FU at the end of that day - not those who finished/.test(await text(page.getByTestId('chef-proposal-targets'))) && /By day 10, 80% of the players of each segment with at least 6 Main dishes/.test(await text(page.getByTestId('chef-proposal-targets'))) && (await page.getByTestId('chef-proposal-judged').locator('button[aria-pressed="true"]').count()) === 9)
  ok('bounds, pacing, locks and how it searches are folded, each with a line saying what is in force', !(await isOpen('chef-proposal-bounds')) && !(await isOpen('chef-proposal-pacing')) && !(await isOpen('chef-proposal-locks')) && !(await isOpen('chef-proposal-search')) && /recipes lean toward 250 · a quantity from 1 · blocker shortage near 3 · Recompletion only reported/.test(await text(fold('chef-proposal-bounds'))) && /at most 0 ordinary ingredients paced · no days typed for a new schedule · the semi-blocker may be given a schedule/.test(await text(fold('chef-proposal-pacing'))) && /Nothing locked · a weight of 0 stays 0/.test(await text(fold('chef-proposal-locks'))) && /Up to 60 versions · 100 players to search, 400 to check/.test(await text(fold('chef-proposal-search'))))
